<?php
declare(strict_types=1);
require_once __DIR__.'/includes/layout.php';require_once __DIR__.'/includes/helpers.php';login_required();$pdo=db();$roomTypes=$pdo->query('SELECT * FROM room_type ORDER BY room_type')->fetchAll();$error='';$success='';
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$action=post('action');
 if($action==='check'){$tc=post('customer_TCno');$type=post('room_type');$in=post('checkin_date');$out=post('checkout_date');$s=$pdo->prepare('SELECT * FROM customer WHERE customer_TCno=? LIMIT 1');$s->execute([$tc]);$customer=$s->fetch();if(!$customer)$error='Customer does not exist';elseif(!$in||!$out||$out<$in)$error='Please provide valid check-in and check-out dates.';else{$rooms=available_rooms($type,$in,$out);if(!$rooms)$error='No available rooms';}}
 elseif($action==='make'){$tc=post('customer_TCno');$room=post_int('room_id');$in=post('checkin_date');$out=post('checkout_date');$s=$pdo->prepare('SELECT * FROM customer WHERE customer_TCno=? LIMIT 1');$s->execute([$tc]);$customer=$s->fetch();if(!$customer)$error='Customer does not exist';elseif($in<date('Y-m-d'))$error="Check-in can't be before today";elseif(!$room||$out<$in)$error='Invalid reservation details';else{try{$pdo->beginTransaction();$available=available_rooms((string)post('room_type'),$in,$out);$ok=false;foreach($available as $rr)if((int)$rr['room_id']===$room)$ok=true;if(!$ok)throw new RuntimeException('Selected room is no longer available.');$pdo->prepare('INSERT INTO reservation(customer_id,room_id,checkin_date,checkout_date,employee_id,reservation_date,status) VALUES(?,?,?,?,?,?,1)')->execute([(int)$customer['customer_id'],$room,$in,$out,(int)user()['employee_id'],date('Y-m-d')]);add_room_sale((int)$customer['customer_id'],$room,$in,$out,(int)user()['employee_id']);$pdo->commit();$success='Reservation successfully made.';}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();$error=$e->getMessage();}}}
}
page_header('Reservation','reservation');?>
<div class="page-head"><div><h1>Reservation</h1><p class="muted">Search available rooms and make a reservation.</p></div><a class="btn success" href="customer.php?reference=reservation">Add Customer</a></div>
<?php if($error):?><div class="alert error"><?=e($error)?></div><?php endif;?><?php if($success):?><div class="alert success"><?=e($success)?></div><?php endif;?>
<section class="card"><form method="post" class="form-grid"><?=csrf_field()?><input type="hidden" name="action" value="check"><label>Customer TC no<input name="customer_TCno" value="<?=e($_POST['customer_TCno']??'')?>" required></label><label>Room Type<select name="room_type" required><?php foreach($roomTypes as $i=>$rt):?><option value="<?=e($rt['room_type'])?>" <?=($_POST['room_type']??'')===$rt['room_type']?'selected':''?>><?=e($rt['room_type'])?></option><?php endforeach;?></select></label><label>Check-in Date<input type="date" name="checkin_date" value="<?=e($_POST['checkin_date']??date('Y-m-d'))?>" required></label><label>Check-out Date<input type="date" name="checkout_date" value="<?=e($_POST['checkout_date']??date('Y-m-d',strtotime('+1 day')))?>" required></label><div class="full"><button class="btn primary">List Available Rooms</button></div></form></section>
<?php if(isset($rooms)&&$rooms):?><section class="card"><h2>Available Rooms</h2><div class="room-grid"><?php foreach($rooms as $r):?><form method="post"><?=csrf_field()?><input type="hidden" name="action" value="make"><input type="hidden" name="customer_TCno" value="<?=e($_POST['customer_TCno'])?>"><input type="hidden" name="room_type" value="<?=e($_POST['room_type'])?>"><input type="hidden" name="checkin_date" value="<?=e($_POST['checkin_date'])?>"><input type="hidden" name="checkout_date" value="<?=e($_POST['checkout_date'])?>"><button class="room-btn" name="room_id" value="<?=$r['room_id']?>" onclick="return confirm('Make reservation for this room?')"><strong><?=$r['room_id']?></strong><span><?=e($r['room_type'])?></span></button></form><?php endforeach;?></div></section><?php endif;?>
<?php page_footer();?>
